.venv/bin/python -c "
import json,csv,re
st={}
for l in open('video_check/state.jsonl'):
    o=json.loads(l); st[o['item_id']]=o
p=list(csv.DictReader(open('video_check/authored_plants.csv')))
tok={'mec000':'hesitat','mec001':'conservative','mec002':'questionnaire','mec003':'blood','mec004':'rate of force','mec005':'less reason','mec006':'gps','mec007':'own devices','mec008':'gabbett','mec009':'tissue','mec010':'pay for','mec011':'software','mec012':'shield','mec013':'turnover battle','mec014':'pay cut','mec015':'donor','mec016':'midweek','mec017':'trust','mec018':'skin','mec019':'marine'}
bad=[]
for r in p:
    pl=st[r['item_id']]; src=st[r['source_item_id']]
    assert pl['passage']==src['passage'], r['item_id']
    assert pl['kind']==r['kind'] and pl['claim']==r['claim']
    if r['kind']=='mechanism':
        hits=len(re.findall(re.escape(tok[r['item_id']]),pl['passage'],re.I))
        print(r['item_id'],tok[r['item_id']],hits)
        if hits: bad.append(r['item_id'])
print('plant passages == source passages: 40/40; mechanism token hits:',bad)
print('digits in plant claims:',sum(bool(re.search(r'\d',r['claim'])) for r in p))
"

